const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul'}).format(new Date()),dt=()=>new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'long',day:'numeric',weekday:'short'}).format(new Date()),timeFmt=x=>x?new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(x)):'—';
const app=$('#app');let user=null,chartInstances=[];const demo=location.hostname==='localhost'||location.hostname==='127.0.0.1';
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}
async function api(path,options={}){let csrf=window.__csrf||'';if(!csrf&&options.method&&options.method!=='GET'&&path!=='/auth/login'&&path!=='/auth/signup'){try{const me=await fetch('/api/auth/me',{credentials:'same-origin'});if(me.ok){const data=await me.json();window.__csrf=csrf=data.csrf||''}}catch{}}if(path==='/auth/login'&&options.body){try{const credentials=JSON.parse(options.body);credentials.returnTo=safeVerifyReturn(sessionStorage.getItem('fp_pending_verify'));options={...options,body:JSON.stringify(credentials)}}catch{}}let r;try{r=await fetch('/api'+path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{}),...(options.headers||{})},...options})}catch{throw Object.assign(new Error('서버에 연결할 수 없습니다. 네트워크 상태를 확인해 주세요.'),{status:0})}let d;try{d=await r.json()}catch{d={error:`서버가 올바르지 않은 응답을 반환했습니다. (HTTP ${r.status})`}}if(path==='/auth/me'&&r.ok&&d.csrf)window.__csrf=d.csrf;if(!r.ok)throw Object.assign(new Error(d.error||`요청에 실패했습니다. (HTTP ${r.status})`),{status:r.status,body:d});return d}
function logo(){return `<a class="brand" href="/"><span class="brand-mark">F</span><span class="brand-name">FactoryPass</span></a>`}
function safeVerifyReturn(value){if(typeof value!=='string'||value.length>256)return null;try{const candidate=new URL(value,location.origin);if(candidate.origin!==location.origin||candidate.pathname!=='/employee/verify'||candidate.search)return null;const token=new URLSearchParams(candidate.hash.slice(1)).get('t');if(!/^[a-f\d]{64}$/i.test(token||''))return null;return `/employee/verify#t=${token}`}catch{return null}}
function landing(){app.innerHTML=`<nav class="landing-nav"><div class="nav-inner">${logo()}<div class="nav-links" id="nav-links"><a href="#features">서비스 소개</a><a href="#features">주요 기능</a><a href="#steps">이용 방법</a></div><div class="nav-actions"><a class="btn" href="/login">로그인</a><a class="btn btn-primary" href="/signup">회원가입</a><button class="menu-toggle" id="menu-toggle" aria-label="메뉴">☰</button></div></div></nav><main><section class="hero"><div><div class="eyebrow">SMART ATTENDANCE FOR MODERN FACTORY</div><h1>QR코드 하나로 완성하는<br><em>스마트 근태관리</em></h1><p class="hero-copy">복잡한 출퇴근 기록은 이제 그만. FactoryPass로 간편하게 출퇴근하고 효율적으로 근태를 관리하세요.</p><div class="hero-actions"><a class="btn btn-primary" href="/login">로그인하고 시작하기 <span>→</span></a><a class="btn" href="/signup">회원가입</a></div><p class="trust-line">관리자가 회사 공용 QR을 발급하고, 근로자가 본인 계정으로 출퇴근을 확인하는 안전한 단일 회사 근태관리</p></div><div class="hero-visual"><div class="hero-blob"></div><div class="preview-card"><div class="preview-head"><span>오늘의 출근 현황</span><span class="live">● 실시간</span></div><div class="preview-stat"><div><strong>24</strong><small>전체 직원</small></div><div><strong>18</strong><small>출근 완료</small></div><div><strong>96<span style="font-size:12px">%</span></strong><small>출근율</small></div></div><div class="preview-row"><span class="avatar">김</span><span><b>김민준</b><small>생산 1팀 · FP-1024</small></span><span class="pill pill-green">정상 출근</span></div><div class="preview-row"><span class="avatar">이</span><span><b>이서연</b><small>품질관리팀 · FP-1031</small></span><span class="pill pill-amber">지각</span></div><div class="preview-row"><span class="avatar">박</span><span><b>박도윤</b><small>생산 2팀 · FP-1048</small></span><span class="pill pill-blue">근무 중</span></div></div><div class="floating-qr"><span class="qr-mini">▦</span><span><b>회사 공용 출퇴근 QR</b><small>30초마다 새로 발급</small></span></div></div></section><section class="section" id="features"><div class="section-inner"><div class="section-heading"><div class="eyebrow">MADE FOR YOUR WORKPLACE</div><h2>근태관리, 더 간편하고 정확하게</h2><p>현장에 필요한 기능만 직관적으로. 직원과 관리자의 하루를 더 가볍게 만듭니다.</p></div><div class="feature-grid">${[['▦','회사 공용 QR 출퇴근','관리자가 발급한 회사 공용 QR을 근로자가 스캔해 출퇴근을 확인합니다.'],['◉','실시간 근태 현황 관리','오늘 출근 현황과 승인 대기 직원을 한눈에 확인합니다.'],['▤','직원별 출퇴근 기록','구성원별 기록을 날짜와 부서 기준으로 간편하게 조회합니다.'],['◷','자동 지각 및 조퇴 판정','등록된 근무 일정에 따라 근태 상태를 자동으로 계산합니다.'],['⌁','근태 통계 및 보고서','기간별·부서별 출근율을 확인하고 CSV로 내려받습니다.'],['▣','PC·모바일 통합 지원','PC, 태블릿, 스마트폰 어디서나 자연스럽게 사용할 수 있습니다.']].map(x=>`<article class="feature-card"><span class="feature-icon">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></div></section><section class="section" id="steps" style="background:#f0f4fa"><div class="section-inner"><div class="section-heading"><div class="eyebrow">SIMPLE WORKFLOW</div><h2>시작부터 출퇴근까지, 다섯 단계</h2><p>회사 공용 QR은 관리자가 발급하며 30초마다 자동 갱신됩니다. 근로자는 본인 계정으로 인증하고 최종 확인을 눌러 기록합니다.</p></div><div class="steps">${['근로자 회원가입','즉시 활성 계정 생성','관리자 공용 QR 발급','근로자 로그인 후 QR 스캔','출퇴근 확인 및 기록'].map((x,i)=>`<div class="step"><span class="step-num">${i+1}</span><strong>${x}</strong></div>`).join('')}</div></div></section><section class="section"><div class="section-inner"><div class="cta-band"><div><div class="eyebrow" style="color:#9bbcff">FACTORYPASS</div><h2 style="margin:10px 0">우리 현장의 근태관리,<br>오늘부터 간편하게</h2><p>근로자 계정으로 가입하고 출퇴근 장소의 공용 QR로 인증하세요.</p></div><a class="btn btn-primary" href="/signup">회원가입 <span>→</span></a></div></div></section></main><footer class="footer"><div class="footer-inner"><div>${logo()}<p>Copyright © ${new Date().getFullYear()} FactoryPass. All rights reserved.</p></div><div class="footer-links"><a href="#features">서비스 소개</a><a href="#" data-static="개인정보처리방침은 회사 환경설정에 따라 고지됩니다.">개인정보처리방침</a><a href="#" data-static="이용약관은 회사 환경설정에 따라 고지됩니다.">이용약관</a><a href="mailto:">문의 안내</a></div></div></footer>`;$('#menu-toggle').onclick=()=>$('#nav-links').classList.toggle('open')}
function authPage(signup=false){app.innerHTML=`<div class="auth-shell"><aside class="auth-side">${logo()}<div class="auth-side-copy"><div class="eyebrow" style="color:#aac5ff">${signup?'JOIN YOUR TEAM':'ATTENDANCE, SIMPLIFIED'}</div><h1>${signup?'현장의 하루를 더 편리하게.':'QR코드 하나로 시작하는\n스마트한 출퇴근.'}</h1><p>FactoryPass는 우리 회사 구성원과 관리자를 위한 근태관리 서비스입니다. 안전하게 로그인하고 오늘의 근태 현황을 확인하세요.</p></div><div class="auth-foot">© ${new Date().getFullYear()} FactoryPass · 단일 회사 근태관리</div></aside><main class="auth-main"><section class="auth-box"><a class="link" href="/">← 메인으로</a><h2>${signup?'근로자 회원가입':'다시 만나 반가워요'}</h2><p class="auth-sub">${signup?'가입하면 즉시 로그인할 수 있습니다.':'계정으로 로그인해 FactoryPass를 이용하세요.'}</p><div class="auth-error" id="auth-error"></div><form id="auth-form">${signup?`<div class="field"><label for="name">이름</label><input id="name" name="name" autocomplete="name" required maxlength="80" placeholder="홍길동"></div><div class="form-row"><div class="field"><label for="employeeNo">사번</label><input id="employeeNo" name="employeeNo" required maxlength="40" placeholder="예: FP-1024"></div><div class="field"><label for="department">부서</label><input id="department" name="department" required maxlength="80" placeholder="예: 생산 1팀"></div></div>`:''}<div class="field"><label for="identity">${signup?'이메일 또는 로그인 아이디':'아이디 또는 이메일'}</label><input id="identity" name="identity" autocomplete="username" required maxlength="120" placeholder="${signup?'이메일 또는 사용할 아이디':'아이디 또는 이메일'}"></div><div class="field"><label for="password">비밀번호</label><div style="display:flex;gap:6px"><input id="password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" required minlength="${signup?'10':'1'}" maxlength="128" placeholder="${signup?'10자 이상 입력해 주세요':'비밀번호를 입력하세요'}"><button type="button" class="small-btn" id="password-toggle">표시</button></div></div>${signup?`<div class="field"><label for="confirm">비밀번호 확인</label><input id="confirm" name="confirm" type="password" autocomplete="new-password" required minlength="10" maxlength="128" aria-describedby="confirm-feedback"><small id="confirm-feedback" class="muted" aria-live="polite"></small></div><label class="check-row"><input type="checkbox" name="consent" required><span>개인정보 수집 및 이용에 동의합니다. 가입 정보는 회사의 근태관리 및 계정 운영 목적으로 사용됩니다.</span></label>`:`<label class="check-row"><input type="checkbox" name="remember" checked><span>로그인 상태 유지 (최대 7일)</span></label>`}<button class="btn btn-primary auth-submit" type="submit">${signup?'가입 신청':'로그인'}</button></form><p class="auth-switch">${signup?'이미 계정이 있으신가요?':'아직 계정이 없으신가요?'} <a href="${signup?'/login':'/signup'}">${signup?'로그인':'회원가입'}</a></p><p class="auth-note">관리자 계정은 일반 회원가입으로 만들 수 없습니다. 최초 관리자 설정은 서버 명령으로 안전하게 진행합니다.</p></section></main></div>`;$('#password-toggle').onclick=()=>{const p=$('#password');p.type=p.type==='password'?'text':'password';$('#password-toggle').textContent=p.type==='password'?'표시':'숨기기'};if(signup){const password=$('#password'),confirm=$('#confirm'),feedback=$('#confirm-feedback');const updateConfirmation=()=>{const hasValue=confirm.value.length>0,matches=hasValue&&password.value===confirm.value;feedback.textContent=!hasValue?'':matches?'비밀번호가 일치합니다.':'비밀번호가 일치하지 않습니다.';feedback.style.color=matches?'var(--green)':'var(--red)';confirm.setCustomValidity(hasValue&&!matches?'비밀번호가 일치하지 않습니다.':'')};password.addEventListener('input',updateConfirmation);confirm.addEventListener('input',updateConfirmation)}$('#auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),err=$('#auth-error');err.style.display='none';const body=signup?{name:f.get('name'),employeeNo:f.get('employeeNo'),department:f.get('department'),identity:f.get('identity'),password:f.get('password'),confirm:f.get('confirm'),consent:f.get('consent')==='on'}:{identity:f.get('identity'),password:f.get('password'),remember:f.get('remember')==='on'};if(signup&&body.password!==body.confirm){err.textContent='비밀번호가 일치하지 않습니다.';err.style.display='block';$('#confirm').focus();return}const submit=$('.auth-submit');submit.disabled=true;try{const result=await api(signup?'/auth/signup':'/auth/login',{method:'POST',body:JSON.stringify(body)});if(signup){location.href='/signup-complete'}else {window.__csrf=result.csrf;sessionStorage.removeItem('fp_pending_verify');location.href=result.redirect||'/';}}catch(x){err.textContent=x.message;err.style.display='block';}finally{submit.disabled=false}}}
const adminLinks=[['/admin','▦','대시보드'],['/admin/employees','♙','직원 관리'],['/admin/attendance','▤','근태 출석부'],['/admin/schedules','◷','근무 일정'],['/admin/statistics','⌁','근태 통계'],['/admin/shared-qr','▣','출퇴근 QR 관리'],['/admin/settings','⚙','환경설정']],employeeLinks=[['/employee','▦','내 대시보드'],['/employee/attendance','▤','내 근태 기록'],['/employee/profile','♙','내 정보']];
function shell(path,title){const admin=path.startsWith('/admin'),links=admin?adminLinks:employeeLinks;app.innerHTML=`<div class="app-layout"><aside class="sidebar" id="sidebar">${logo()}<div class="workspace"><span class="avatar">${esc((user?.name||'F')[0])}</span><div><strong>${esc(user?.name||'사용자')}</strong><small>${admin?'관리자':'근로자'} · ${esc(user?.department||'FactoryPass')}</small></div></div><div class="side-label">${admin?'WORKSPACE':'MY ATTENDANCE'}</div><nav class="side-nav">${links.map(l=>`<a class="side-link ${l[0]===path?'active':''}" href="${l[0]}" ${l[3]==='new-tab'?'target="_blank" rel="noopener noreferrer"':''}><span class="side-symbol">${l[1]}</span>${l[2]}</a>`).join('')}</nav><div class="side-bottom">안전한 회사 전용 근태관리</div></aside><main class="main-area"><header class="topbar"><button class="mobile-menu" id="side-toggle" aria-label="메뉴">☰</button><div class="top-title">${title}</div><div class="top-meta"><span class="top-date">${dt()}</span><span class="user-chip"><span class="avatar">${esc((user?.name||'F')[0])}</span><span>${esc(user?.name||'')}</span></span><button class="small-btn" id="logout">로그아웃</button></div></header><div class="content" id="view"></div>${!admin?`<nav class="employee-mobile-nav">${links.map(l=>`<a class="${l[0]===path?'active':''}" href="${l[0]}"><b>${l[1]}</b>${l[2].replace('내 ','')}</a>`).join('')}</nav>`:''}</main></div>`;$('#side-toggle').onclick=()=>$('#sidebar').classList.toggle('open');$('#logout').onclick=async()=>{try{await api('/auth/logout',{method:'POST',body:'{}'})}catch{}location.href='/'};return $('#view')}
const empty=(msg='표시할 데이터가 없습니다.')=>`<div class="empty"><div class="empty-icon">◎</div>${msg}</div>`,badge=(s)=>`<span class="pill ${s==='정상 출근'||s==='퇴근 완료'||s==='승인됨'?'pill-green':s==='지각'||s==='승인 대기'?'pill-amber':s==='미출근'||s==='결근'?'pill-red':'pill-blue'}">${esc(s||'—')}</span>`,shortDate=s=>s?new Date(`${s}T00:00:00+09:00`).toLocaleDateString('ko-KR',{month:'numeric',day:'numeric'}):'—';
async function loadAdminHome(v){try{const d=await api('/admin/dashboard');v.innerHTML=`<div class="page-head"><div><h1>안녕하세요, ${esc(user.name)}님</h1><p>오늘의 근태 현황을 확인하세요. <b>${dt()}</b></p></div></div><div class="stats-grid">${[['전체 직원',d.stats.total,'등록된 근로자'],['오늘 출근',d.stats.present,'오늘 출근한 직원'],['정상 출근',d.stats.normal,'출근 상태 직원'],['지각',d.stats.late,'일정 기준 판정'],['미출근',d.stats.absent,'오늘 출근 기록 없음'],['퇴근 완료',d.stats.checkedOut,'오늘 퇴근 인증 직원']].map((x,i)=>`<article class="stat-card"><div class="stat-label"><i class="stat-accent" style="background:${['#2766dc','#15966d','#15966d','#d99a2b','#d24d57','#5580d9'][i]}"></i>${x[0]}</div><div class="stat-value">${x[1]??0}</div><div class="stat-note">${x[2]}</div></article>`).join('')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>최근 출퇴근 기록</h2><p>QR 인증으로 저장된 최신 이벤트</p></div><a class="link" href="/admin/attendance">전체 보기 →</a></div>${d.recent?.length?`<div class="table-wrap"><table><thead><tr><th>직원</th><th>부서</th><th>유형</th><th>인증 시간</th><th>상태</th></tr></thead><tbody>${d.recent.map(r=>`<tr><td>${esc(r.name)} <small class="muted">${esc(r.employee_no)}</small></td><td>${esc(r.department||'—')}</td><td>${r.event_type==='out'||r.check_out?'퇴근':'출근'}</td><td>${timeFmt(r.occurred_at||r.check_out||r.check_in)}</td><td>${badge(r.status||'근무 중')}</td></tr>`).join('')}</tbody></table></div>`:empty('아직 출퇴근 기록이 없습니다.')}</section><div class="stack"><section class="panel"><div class="panel-head"><div><h2>최근 7일 출근율</h2><p>근무일정 기준 출근율</p></div></div><div class="chart-area"><canvas id="home-chart"></canvas></div></section></div></div>`;drawChart($('#home-chart'),d.trend?.labels||[],d.trend?.values||[])}catch(e){v.innerHTML=`<div class="notice">데이터를 불러오지 못했습니다: ${esc(e.message)}. D1 데이터베이스 바인딩과 관리자 초기 설정을 확인해 주세요.</div>`}}
function drawChart(canvas,labels,values,type='line'){if(!canvas||!window.Chart)return;chartInstances.forEach(c=>c.destroy());chartInstances=[];chartInstances.push(new Chart(canvas,{type,data:{labels,datasets:[{label:'출근율(%)',data:values,borderColor:'#2766dc',backgroundColor:'rgba(39,102,220,.12)',fill:true,tension:.35,pointRadius:3}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,max:100,ticks:{callback:v=>v+'%'}},x:{grid:{display:false}}}}}))}
async function employees(v){v.innerHTML=`<div class="page-head"><div><h1>직원 관리</h1><p>직원 계정과 이용 상태를 관리합니다.</p></div></div><div class="panel table-panel"><div class="toolbar"><div class="toolbar-group"><input id="employee-search" type="search" placeholder="이름, 사번 또는 이메일 검색"><select id="employee-status"><option value="">모든 계정 상태</option><option value="pending">기존 승인 대기</option><option value="approved">활성</option><option value="disabled">비활성</option><option value="rejected">거절됨</option></select><select id="employee-dept"><option value="">모든 부서</option></select></div><span class="muted" id="employee-count"></span></div><div id="employee-table"></div></div>`;let rows=[];try{({employees:rows}=await api('/admin/employees'))}catch(e){$('#employee-table').innerHTML=empty(esc(e.message));return}const depts=[...new Set(rows.map(x=>x.department?.trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ko'));$('#employee-dept').innerHTML='<option value="">모든 부서</option>'+depts.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');const render=()=>{const q=$('#employee-search').value.trim().toLocaleLowerCase('ko'),s=$('#employee-status').value,d=$('#employee-dept').value,filtered=rows.filter(x=>(!q||`${x.name||''} ${x.employee_no||''} ${x.email||''} ${x.username||''}`.toLocaleLowerCase('ko').includes(q))&&(!s||x.status===s)&&(!d||x.department?.trim()===d));$('#employee-count').textContent=`${filtered.length}명`;$('#employee-table').innerHTML=filtered.length?`<div class="table-wrap"><table><thead><tr><th>이름</th><th>사번</th><th>부서</th><th>이메일 / 아이디</th><th>가입일</th><th>상태</th><th>관리</th></tr></thead><tbody>${filtered.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.employee_no)}</td><td>${esc(x.department||'—')}</td><td>${esc(x.email||x.username)}</td><td>${shortDate(x.created_at?.slice(0,10))}</td><td>${badge(({pending:'기존 승인 대기',approved:'활성',disabled:'비활성',rejected:'사용 제한'})[x.status]||x.status)}</td><td><div class="table-actions">${x.status==='disabled'?`<button class="small-btn" data-enable="${x.id}">재활성화</button>`:x.status==='approved'?`<button class="small-btn" data-disable="${x.id}">비활성화</button>`:''}<button class="small-btn" data-records="${x.id}">근태</button></div></td></tr>`).join('')}</tbody></table></div>`:empty()};$('#employee-search').oninput=render;$('#employee-status').onchange=render;$('#employee-dept').onchange=render;render();$('#employee-table').onclick=async e=>{const b=e.target.closest('button[data-disable],button[data-enable],button[data-records]');if(!b)return;if(b.dataset.records){location.href='/admin/attendance?employee='+encodeURIComponent(b.dataset.records);return}const action=b.dataset.disable?'disable':'enable';try{await api(`/admin/employees/${b.dataset.disable||b.dataset.enable}/${action}`,{method:'POST',body:'{}'});toast('계정 상태를 변경했습니다.');employees(v)}catch(x){toast(x.message)}}}
async function attendance(v,employeeFilter=''){v.innerHTML=`<div class="page-head"><div><h1>근태 출석부</h1><p>기존 일일 기록과 회사 공용 QR 출퇴근 이벤트를 시간순으로 조회합니다.</p></div><button class="btn" id="csv">↓ CSV 다운로드</button></div><div class="panel table-panel"><div class="toolbar"><div class="toolbar-group"><input type="date" id="att-from"><input type="date" id="att-to"><input type="search" id="att-search" placeholder="이름 또는 사번"><select id="att-status"><option value="">모든 근태 상태</option>${['정상 출근','지각','근무 중','퇴근 완료','미출근','결근'].map(x=>`<option>${x}</option>`).join('')}</select></div><button class="btn btn-soft" id="att-load">조회</button></div><div id="attendance-table"></div></div>`;$('#att-from').value=today();$('#att-to').value=today();async function load(){const p=new URLSearchParams({from:$('#att-from').value,to:$('#att-to').value,search:$('#att-search').value,status:$('#att-status').value});if(employeeFilter)p.set('employee',employeeFilter);try{const d=await api('/admin/attendance?'+p);$('#attendance-table').innerHTML=d.records.length?`<div class="table-wrap"><table><thead><tr><th>날짜</th><th>사번</th><th>직원 이름</th><th>부서</th><th>시간</th><th>유형</th><th>기록 방식</th><th>상태</th><th>관리</th></tr></thead><tbody>${d.records.map(r=>`<tr><td>${esc(r.work_date)}</td><td>${esc(r.employee_no)}</td><td><b>${esc(r.name)}</b></td><td>${esc(r.department||'—')}</td><td>${timeFmt(r.occurred_at)}</td><td>${r.event_type==='in'?'출근':r.event_type==='out'?'퇴근':'기존 일일 기록'}</td><td>${r.source==='shared_qr'?'회사 공용 QR':'기존 기록'}</td><td>${badge(r.status)}</td><td>${r.source==='legacy'?`<button class="small-btn" data-edit-record="${r.id}" data-in="${r.check_in||''}" data-out="${r.check_out||''}">수정</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('선택한 조건의 기록이 없습니다.')}catch(e){$('#attendance-table').innerHTML=empty(esc(e.message))}}$('#att-load').onclick=load;load();$('#csv').onclick=async()=>{try{const p=new URLSearchParams({from:$('#att-from').value,to:$('#att-to').value});const r=await fetch('/api/admin/attendance.csv?'+p,{credentials:'same-origin'});if(!r.ok)throw new Error((await r.json()).error);const a=document.createElement('a');a.href=URL.createObjectURL(await r.blob());a.download=`factorypass-attendance-${today()}.csv`;a.click();URL.revokeObjectURL(a.href)}catch(e){toast(e.message)}};$('#attendance-table').onclick=async e=>{const b=e.target.closest('[data-edit-record]');if(!b)return;const checkIn=prompt('출근 시각 (ISO 형식, 비우면 변경 없음)',b.dataset.in);if(checkIn===null)return;const checkOut=prompt('퇴근 시각 (ISO 형식, 비우면 변경 없음)',b.dataset.out);if(checkOut===null)return;const reason=prompt('수정 사유를 입력하세요');if(!reason)return;try{await api(`/admin/attendance/${b.dataset.editRecord}`,{method:'PATCH',body:JSON.stringify({checkIn:checkIn||null,checkOut:checkOut||null,reason})});toast('기존 기록과 수정 이력을 저장했습니다.');load()}catch(x){toast(x.message)}}}
async function legacyCameraScanner(v){v.innerHTML=`<div class="page-head"><div><h1>QR 스캐너</h1><p>승인된 직원의 오늘 QR을 스캔해 출퇴근을 기록합니다.</p></div><div class="mode-toggle"><button class="active" data-mode="in">출근</button><button data-mode="out">퇴근</button></div></div><div class="scanner-layout"><section class="panel"><div class="panel-head"><div><h2>카메라 스캔</h2><p>HTTPS 연결 및 카메라 권한이 필요합니다.</p></div></div><div class="scanner-frame" id="reader"><div class="scanner-placeholder">카메라 시작을 눌러 스캐너를 실행하세요.</div></div><div class="toolbar" style="padding:14px 0;border:0"><button class="btn btn-primary" id="start-camera">카메라 시작</button><button class="btn" id="stop-camera" disabled>카메라 종료</button><select id="camera-select" aria-label="카메라 선택"><option>카메라 선택</option></select></div><div class="notice">관리자가 출근/퇴근 모드를 선택한 후 QR을 스캔합니다. 동일 QR을 연속 인식해도 중복 기록은 서버에서 차단됩니다.</div></section><section class="panel"><div class="panel-head"><div><h2>인증 결과</h2><p>가장 최근 스캔 정보</p></div></div><div id="scan-result" class="empty">아직 스캔 결과가 없습니다.</div></section></div>`;let mode='in',scannerObj=null,busy=false,seen=new Map();$$('[data-mode]',v).forEach(b=>b.onclick=()=>{$$('[data-mode]',v).forEach(x=>x.classList.toggle('active',x===b));mode=b.dataset.mode});const result=$('#scan-result');async function onScan(text){if(busy||seen.has(text))return;busy=true;seen.set(text,Date.now());setTimeout(()=>seen.delete(text),4000);try{const d=await api('/admin/scan',{method:'POST',body:JSON.stringify({token:text,mode})});result.className='scanner-result';result.innerHTML=`<div class="profile-intro"><span class="avatar">${esc(d.employee.name[0])}</span><div><h2>${esc(d.employee.name)}</h2><p>${esc(d.employee.employee_no)} · ${esc(d.employee.department||'')}</p></div>${badge(d.status)}</div><div class="today-status"><div class="time-tile"><small>인증 구분</small><strong>${mode==='in'?'출근':'퇴근'}</strong></div><div class="time-tile"><small>인증 시간 (한국 표준시)</small><strong>${timeFmt(d.recordedAt)}</strong></div></div><p class="notice" style="margin-top:14px">${esc(d.message||'인증 성공 · 기록을 저장했습니다.')}</p>`;toast('출퇴근 기록이 저장되었습니다.')}catch(e){result.className='notice';result.innerHTML=`<b>인증 실패</b><br>${esc(e.message)}`}finally{setTimeout(()=>busy=false,1300)}}$('#start-camera').onclick=async()=>{try{if(!window.Html5Qrcode)throw new Error('QR 스캐너 라이브러리를 불러오지 못했습니다. 네트워크 연결을 확인하세요.');scannerObj=new Html5Qrcode('reader');const cameras=await Html5Qrcode.getCameras();if(!cameras.length)throw new Error('사용 가능한 카메라를 찾지 못했습니다.');$('#camera-select').innerHTML=cameras.map((c,i)=>`<option value="${esc(c.id)}">${esc(c.label||`카메라 ${i+1}`)}</option>`).join('');await scannerObj.start(cameras[0].id,{fps:10,qrbox:{width:230,height:230}},onScan,()=>{});$('#start-camera').disabled=true;$('#stop-camera').disabled=false}catch(e){toast(e.message);$('#reader').innerHTML=`<div class="scanner-placeholder">${esc(e.message)}<br>브라우저 카메라 권한을 허용하고 HTTPS 환경에서 다시 시도하세요.</div>`}};$('#stop-camera').onclick=async()=>{try{await scannerObj?.stop();scannerObj?.clear()}catch{}scannerObj=null;$('#start-camera').disabled=false;$('#stop-camera').disabled=true;$('#reader').innerHTML='<div class="scanner-placeholder">카메라가 종료되었습니다.</div>'};$('#camera-select').onchange=async e=>{if(!scannerObj)return;try{await scannerObj.stop();await scannerObj.start(e.target.value,{fps:10,qrbox:{width:230,height:230}},onScan,()=>{})}catch(x){toast(x.message)}}}
async function schedules(v){v.innerHTML=`<div class="page-head"><div><h1>근무 일정</h1><p>기본 근무시간과 부서별 일정을 관리합니다. 야간 일정은 퇴근일이 다음 날로 자동 계산됩니다.</p></div></div><div class="settings-grid"><section class="panel"><div class="panel-head"><div><h2 id="schedule-form-title">기본 근무시간</h2><p>회사 기본 일정 및 지각 판정 기준</p></div></div><form id="schedule-form"><div class="form-row"><div class="field"><label>출근 시간</label><input type="time" name="startTime" value="09:00" required></div><div class="field"><label>퇴근 시간</label><input type="time" name="endTime" value="18:00" required></div></div><div class="field"><label>지각 유예 (분)</label><input type="number" name="graceMinutes" value="5" min="0" max="180"></div><div class="field"><label>일정 유형</label><select name="scope"><option value="default">회사 기본</option><option value="department">부서별</option><option value="employee">직원별</option></select></div><div class="field hidden" id="scope-target"><label>부서명 또는 사번</label><input name="target" maxlength="80"></div><div class="toolbar-group"><button class="btn btn-primary" id="schedule-submit">일정 저장</button><button class="btn hidden" id="schedule-cancel" type="button">수정 취소</button></div></form></section><section class="panel"><div class="panel-head"><div><h2>등록된 일정</h2><p>적용 우선순위: 직원별 → 부서별 → 기본</p></div></div><div id="schedule-list">불러오는 중…</div></section></div><section class="panel" style="margin-top:15px"><div class="panel-head"><div><h2>휴무일</h2><p>근무일정에서 제외할 날짜를 등록합니다.</p></div></div><div class="toolbar"><div class="toolbar-group"><input type="date" id="holiday-date"><input id="holiday-name" placeholder="휴무명"></div><button class="btn btn-soft" id="holiday-add">휴무일 등록</button></div><div id="holiday-list"></div></section>`;const form=$('#schedule-form'),scheduleList=$('#schedule-list'),scheduleTitle=$('#schedule-form-title'),scheduleSubmit=$('#schedule-submit'),scheduleCancel=$('#schedule-cancel');let schedulesList=[];function resetScheduleForm(){form.reset();form.scope.value='default';$('#scope-target').classList.add('hidden');scheduleTitle.textContent='기본 근무시간';scheduleSubmit.textContent='일정 저장';scheduleCancel.classList.add('hidden')}function renderSchedules(){scheduleList.innerHTML=schedulesList.length?`<div class="table-wrap"><table><thead><tr><th>적용 대상</th><th>출근</th><th>퇴근</th><th>유예</th><th>관리</th></tr></thead><tbody>${schedulesList.map(x=>`<tr><td>${esc(x.scope==='default'?'회사 기본':x.target||x.scope)}</td><td>${esc(x.start_time)}</td><td>${esc(x.end_time)}</td><td>${x.grace_minutes}분</td><td><button class="small-btn" data-schedule-edit="${x.id}">수정</button></td></tr>`).join('')}</tbody></table></div>`:empty()}try{const d=await api('/admin/schedules');schedulesList=d.schedules;renderSchedules()}catch(e){scheduleList.innerHTML=empty(esc(e.message))}scheduleList.onclick=e=>{const button=e.target.closest('[data-schedule-edit]');if(!button)return;const item=schedulesList.find(x=>String(x.id)===button.dataset.scheduleEdit);if(!item)return;form.scope.value=item.scope;form.target.value=item.target||'';form.startTime.value=item.start_time;form.endTime.value=item.end_time;form.graceMinutes.value=item.grace_minutes;$('#scope-target').classList.toggle('hidden',item.scope==='default');scheduleTitle.textContent='근무 일정 수정';scheduleSubmit.textContent='변경 저장';scheduleCancel.classList.remove('hidden');form.scrollIntoView({behavior:'smooth',block:'center'})};scheduleCancel.onclick=resetScheduleForm;const loadHolidays=async()=>{try{const d=await api('/admin/holidays');$('#holiday-list').innerHTML=d.holidays.length?d.holidays.map(h=>`<div class="mini-item" style="padding:11px 0;border-bottom:1px solid var(--line)"><div class="mini-info"><b>${esc(h.holiday_date)}</b><small>${esc(h.name||'휴무')}</small></div><button class="small-btn" data-holiday-del="${h.id}">삭제</button></div>`).join(''):empty()}catch(e){$('#holiday-list').innerHTML=empty(esc(e.message))}};loadHolidays();form.scope.onchange=()=>$('#scope-target').classList.toggle('hidden',form.scope.value==='default');form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);scheduleSubmit.disabled=true;try{await api('/admin/schedules',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});toast('근무 일정을 저장했습니다.');resetScheduleForm();const updated=await api('/admin/schedules');schedulesList=updated.schedules;renderSchedules()}catch(x){toast(x.message)}finally{scheduleSubmit.disabled=false}};$('#holiday-add').onclick=async()=>{try{await api('/admin/holidays',{method:'POST',body:JSON.stringify({date:$('#holiday-date').value,name:$('#holiday-name').value})});toast('휴무일을 등록했습니다.');loadHolidays()}catch(e){toast(e.message)}};$('#holiday-list').onclick=async e=>{const b=e.target.closest('[data-holiday-del]');if(!b)return;try{await api('/admin/holidays/'+b.dataset.holidayDel,{method:'DELETE'});loadHolidays()}catch(x){toast(x.message)}}}
