async function employeeVerifyPage(token){app.innerHTML=`<main class="auth-main verify-shell"><section class="auth-box verify-card">${logo()}<div class="eyebrow">SHARED QR ATTENDANCE</div><h1>회사 공용 QR 출퇴근 인증</h1><div id="verify-state" class="notice" role="status" aria-live="polite">공용 QR과 근로자 계정을 확인하고 있습니다.</div><div id="verify-content"></div></section></main>`;const state=$('#verify-state'),content=$('#verify-content');if(!/^[a-f\d]{64}$/i.test(token||'')){state.textContent='공용 QR 주소가 올바르지 않습니다. 회사 출퇴근 장소에서 새 QR을 촬영해 주세요.';return}let data;try{data=await api('/employee/qr/verify',{method:'POST',body:JSON.stringify({token})})}catch(error){state.textContent=error.status===410?'공용 QR이 만료되었습니다. 회사 출퇴근 장소에서 최신 QR을 다시 촬영해 주세요.':error.status===423?'공용 QR이 중지되었습니다. 관리자에게 문의해 주세요.':error.status===409?error.message:error.status===401?'로그인이 필요합니다. QR을 다시 촬영하고 근로자 계정으로 로그인해 주세요.':error.message;content.innerHTML=error.status===401?'<a class="btn" href="/login">근로자 로그인</a>':'';return}state.textContent='공용 QR 확인 완료 · 인증 유예시간 60초';const expires=Date.parse(data.claimExpiresAt),render=()=>{const left=Math.max(0,Math.ceil((expires-Date.now())/1000));$('#verify-countdown').textContent=`확인 가능 시간 ${left}초`;if(left<=0){$('#verify-confirm').disabled=true;state.textContent='인증 유예시간이 만료되었습니다. 새 공용 QR을 촬영해 주세요.'}};content.innerHTML=`<div class="verify-employee"><span class="avatar">${esc(data.employee.name[0])}</span><div><strong>${esc(data.employee.name)}</strong><small>${esc(data.employee.employeeNo)} · ${esc(data.employee.department||'부서')}</small></div></div><div class="time-tile"><small>출퇴근 예정</small><strong>${data.previewType==='in'?'출근':'퇴근'}</strong></div><p id="verify-countdown" class="muted"></p><p class="muted">QR 만료 ${timeFmt(data.qrExpiresAt)} · 서버 확인 ${timeFmt(data.serverTime)}</p><button class="btn btn-primary" id="verify-confirm" type="button">${data.previewType==='in'?'출근 확인':'퇴근 확인'}</button><div class="notice hidden" id="verify-result" style="margin-top:14px" role="status" aria-live="polite"></div>`;render();const timer=setInterval(render,1000),confirm=$('#verify-confirm');confirm.addEventListener('click',async()=>{if(confirm.disabled)return;confirm.disabled=true;state.textContent='출퇴근 인증을 저장하고 있습니다…';try{const result=await api('/employee/qr/confirm',{method:'POST',body:JSON.stringify({claimId:data.claimId,requestId:crypto.randomUUID()})});$('#verify-result').classList.remove('hidden');$('#verify-result').textContent=`${result.employee.name}님 ${result.message} · ${result.seoulTime}`;confirm.textContent=`${result.eventType==='in'?'출근':'퇴근'} 완료`;state.textContent='출퇴근 인증 완료';clearInterval(timer)}catch(error){state.textContent=error.status===410?'인증 유예시간이 만료되었습니다. 회사 출퇴근 장소에서 QR을 다시 촬영해 주세요.':error.status===423?'회사 공용 QR이 중지되어 인증을 취소했습니다.':error.status===409?'이 인증 요청은 이미 처리되었거나 출퇴근 상태가 변경되었습니다. 새 QR을 촬영해 주세요.':error.message;confirm.disabled=true;clearInterval(timer)}})}

async function employeeAttendance(v){v.innerHTML=`<div class="page-head"><div><h1>내 근태 기록</h1><p>본인의 출퇴근 내역과 월별 현황입니다.</p></div></div><div class="stats-grid" id="my-stats"></div><section class="panel table-panel"><div class="toolbar"><div class="toolbar-group"><input type="date" id="my-from"><input type="date" id="my-to"></div><button class="btn btn-soft" id="my-load">조회</button></div><div id="my-table"></div></section>`;$('#my-to').value=today();const d=new Date();d.setDate(1);$('#my-from').value=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul'}).format(d);async function load(){try{const x=await api(`/employee/attendance?from=${$('#my-from').value}&to=${$('#my-to').value}`);$('#my-stats').innerHTML=[['출근 이벤트',x.summary.present],['퇴근 이벤트',x.summary.checkouts],['미완료 근무 구간',x.summary.openShifts],['근무 시간',`${Math.floor(x.summary.minutes/60)}시간`]].map(a=>`<article class="stat-card"><div class="stat-label">${a[0]}</div><div class="stat-value">${a[1]}</div></article>`).join('');$('#my-table').innerHTML=x.records.length?`<div class="table-wrap"><table><thead><tr><th>날짜</th><th>시각</th><th>유형</th><th>인증 경로</th></tr></thead><tbody>${x.records.map(r=>`<tr><td>${esc(r.work_date)}</td><td>${timeFmt(r.occurred_at)}</td><td>${badge(r.event_type==='in'?'출근':'퇴근')}</td><td>${esc(r.source==='shared_qr'?'회사 공용 QR':'기존 기록')}</td></tr>`).join('')}</tbody></table></div>`:empty()}catch(e){$('#my-table').innerHTML=empty(esc(e.message))}}$('#my-load').onclick=load;load()}
async function profile(v){v.innerHTML=`<div class="page-head"><div><h1>내 정보</h1><p>이름, 사번, 부서는 회사 관리자만 변경할 수 있습니다. 수정이 필요하면 관리자에게 요청하세요.</p></div></div><div class="settings-grid"><section class="panel"><div class="panel-head"><h2>계정 정보</h2></div><div class="field"><label>이름</label><input disabled value="${esc(user.name)}"></div><div class="field"><label>사번</label><input disabled value="${esc(user.employee_no)}"></div><div class="field"><label>부서</label><input disabled value="${esc(user.department||'—')}"></div><div class="field"><label>로그인 아이디 / 이메일</label><input disabled value="${esc(user.email||user.username)}"></div></section><section class="panel"><div class="panel-head"><h2>비밀번호 변경</h2></div><form id="profile-password"><div class="field"><label>현재 비밀번호</label><input name="currentPassword" type="password" required></div><div class="field"><label>새 비밀번호 (10자 이상)</label><input name="newPassword" type="password" minlength="10" required></div><button class="btn btn-primary">비밀번호 변경</button></form></section></div>`;$('#profile-password').onsubmit=async e=>{e.preventDefault();try{await api('/auth/password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});toast('비밀번호가 변경되었습니다.')}catch(x){toast(x.message)}}}
function signupComplete(){app.innerHTML=`<div class="auth-main" style="min-height:100vh"><div class="pending-box"><div class="pending-icon" style="background:#e6f5ee;color:#13805e">✓</div>${logo()}<h1>회원가입이 완료되었습니다.</h1><p>회원가입이 완료되었습니다. 로그인해 주세요.</p><a class="btn btn-primary" href="/login">로그인</a></div></div>`}
function staticError(msg){app.innerHTML=`<div class="auth-main" style="min-height:100vh"><section class="auth-box"><div class="brand-mark">F</div><h2>FactoryPass에 연결할 수 없습니다</h2><p class="auth-sub">${esc(msg)}</p><p class="auth-note">이 서비스는 Cloudflare Pages Functions와 D1 데이터베이스를 구성해야 실제로 작동합니다. README의 배포 설정을 확인하세요.</p><a class="btn btn-primary" href="/">메인으로</a></section></div>`}
﻿async function boot(){
 clearTimeout(window.__factoryPassBootTimer);
 const path=location.pathname.replace(/\/$/,'')||'/';
 if(path==='/privacy'||path==='/terms'){landing();return}

 if(path==='/signup-complete'){signupComplete();return}
 if(path==='/'){
  try{const d=await api('/auth/me');user=d.user;window.__csrf=d.csrf;location.replace(d.redirect);return}catch{landing();return}
 }
 if(path==='/login'||path==='/signup'){
  try{const d=await api('/auth/me');user=d.user;window.__csrf=d.csrf;const next=path==='/login'&&user.role==='employee'?safeVerifyReturn(new URLSearchParams(location.search).get('next')):null;location.replace(next||d.redirect);return}catch(e){if(e.status===403){location.href='/login';return}}
  authPage(path==='/signup');return;
 }
 if(path==='/pending'){location.replace('/login');return}
  if(path==='/employee/verify'){
  const returnPath=safeVerifyReturn(path+location.hash);
  if(!returnPath){employeeVerifyPage('');return}
  try{const d=await api('/auth/me');user=d.user;window.__csrf=d.csrf;if(user.role!=='employee'){location.replace(user.role==='admin'?'/admin':'/login');return}if(user.status!=='approved'){location.replace('/login');return}}
  catch{sessionStorage.setItem('fp_pending_verify',returnPath);location.replace('/login');return}
  const token=new URLSearchParams(location.hash.slice(1)).get('t');await employeeVerifyPage(token);return;
 }
 if(path.startsWith('/admin')||path.startsWith('/employee')){
  try{const d=await api('/auth/me');user=d.user;window.__csrf=d.csrf;if(!d.user||d.user.status!=='approved'){location.replace(d.redirect||'/login');return}const admin=path.startsWith('/admin');if(admin&&user.role!=='admin'||!admin&&user.role!=='employee'){location.replace(user.role==='admin'?'/admin':'/employee');return}}
  catch{location.replace('/login');return}
 const titles={'/admin':'대시보드','/admin/employees':'직원 관리','/admin/shared-qr':'출퇴근 QR 관리','/admin/attendance':'근태 출석부','/admin/schedules':'근무 일정','/admin/statistics':'근태 통계','/admin/settings':'환경설정','/employee':'내 대시보드','/employee/attendance':'내 근태 기록','/employee/profile':'내 정보'};
  const title=titles[path];if(!title){staticError('요청한 페이지를 찾을 수 없습니다.');return}
  const view=shell(path,title);
 if(path==='/admin')loadAdminHome(view);else if(path==='/admin/employees')employees(view);else if(path==='/admin/shared-qr')sharedQrAdmin(view);else if(path==='/admin/attendance')attendance(view,new URLSearchParams(location.search).get('employee')||'');else if(path==='/admin/schedules')schedules(view);else if(path==='/admin/statistics')statistics(view);else if(path==='/admin/settings')settings(view);else if(path==='/employee')employeeHome(view);else if(path==='/employee/attendance')employeeAttendance(view);else profile(view);
  return;
 }
 staticError('페이지를 찾을 수 없습니다.');
}
document.addEventListener('click',e=>{const x=e.target.closest('[data-static]');if(x){e.preventDefault();toast(x.dataset.static)}});window.addEventListener('error',e=>{if(e.target instanceof HTMLScriptElement||e.target instanceof HTMLLinkElement){const app=$('#app');if(app?.querySelector('.boot'))staticError('정적 리소스를 불러오지 못했습니다. 페이지를 새로고침해 주세요.')}else if($('#app')?.querySelector('.boot'))staticError('페이지 초기화 중 오류가 발생했습니다. 새로고침해 주세요.')},true);window.addEventListener('unhandledrejection',e=>{toast(e.reason?.message||'요청 처리 중 문제가 발생했습니다.');e.preventDefault()});try{boot().catch(error=>staticError(error?.message||'페이지 초기화 중 오류가 발생했습니다. 새로고침해 주세요.'))}catch(error){staticError(error?.message||'페이지 초기화 중 오류가 발생했습니다. 새로고침해 주세요.')}
